        { "goto", x = 58.4, y = 78.8, zone = "2521" },
        { "finish", quest = 97257, text = "Finish Call of Fire: Brazier of Offering, Brazier of Eternal Flame (the ritual, then the |cOXP_FRIENDLY_Brazier of Eternal Flame|r in Valanaar)" },
