      { only = "Paladin", when = { { "level", n = 9, neg = true } },
        { "text", text = "|cOXP_FRIENDLY_Shari Stilwell|r" },
        { "text", text = "Follow the road east out of Deathknell to Brill. |cOXP_FRIENDLY_Shari Stilwell|r, the paladin trainer, stands in town; she trains you from here on." },
        { "goto", x = 60.22, y = 52.66, zone = "1420" },
        { "turnin", quest = 91209, text = "Turn in Continue Your Training (|cOXP_FRIENDLY_Shari Stilwell|r, Brill)" },
