      { only = "NightElf Druid",
        { "text", text = "Class quest: {spell:5487} and {area:493}" },
        { "text", text = "Heeding the Call" },
        { "text", text = "At 10 a druid's call reaches you: |cOXP_FRIENDLY_Kal|r in Dolanaar, Denatharion in Darnassus or Theridran in Stormwind. Any one of them sends you to |cOXP_FRIENDLY_Mathrengyl Bearwalker|r in the Cenarion Enclave of Darnassus." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 55.95, y = 61.56, zone = "1438" },
        { "accept", optional = true, quest = 5925, text = "Accept Heeding the Call (|cOXP_FRIENDLY_Kal|r, Dolanaar; Denatharion's and Theridran's letters lead to the same place)" },
        { "target", name = "Kal" },
      },
      { only = "NightElf Druid",
        { "text", text = "Cenarion Enclave" },
        { "text", text = "|cOXP_FRIENDLY_Mathrengyl Bearwalker|r stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab)." },
        { "reach", text = "Cenarion Enclave", x = 35.8, y = 11.6, zone = "1457" },
      },
      { only = "NightElf Druid",
        { "text", text = "|cOXP_FRIENDLY_Mathrengyl Bearwalker|r" },
        { "text", text = "|cOXP_FRIENDLY_Mathrengyl Bearwalker|r stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab)." },
