        { "target", name = "Mathrengyl Bearwalker" },
      },
      { only = "Tauren Druid",
        { "text", text = "Heeding the Call" },
        { "text", text = "At 10 a druid's call reaches you: |cOXP_FRIENDLY_Gennia Runetotem|r in Bloodhoof Village or |cOXP_FRIENDLY_Innkeeper Pala|r in Thunder Bluff (|cOXP_FRIENDLY_Innkeeper Gryshka|r's letter in Orgrimmar works too). Any one of them sends you to |cOXP_FRIENDLY_Turak Runetotem|r on Elder Rise in Thunder Bluff." },
        { "xp", level = 10, text = "Reach level 10" },
        { "goto", x = 47.48, y = 62.95, zone = "1412" },
        { "accept", optional = true, quest = 5928, text = "Accept Heeding the Call (|cOXP_FRIENDLY_Gennia Runetotem|r, Bloodhoof Village; Pala's and Gryshka's letters lead to the same place)" },
        { "target", name = "Gennia Runetotem" },
      },
      { only = "Tauren Druid",
        { "text", text = "|cOXP_FRIENDLY_Turak Runetotem|r" },
        { "text", text = "|cOXP_FRIENDLY_Turak Runetotem|r stands in the druids' hut on Elder Rise, over the rope bridges east of the lifts. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab)." },
