        { "text", text = "Cenarion Enclave" },
        { "text", text = "|cOXP_FRIENDLY_Mathrengyl Bearwalker|r, upstairs in the Cenarion Enclave, teaches you Cure Poison." },
        { "reach", text = "Cenarion Enclave", x = 35.8, y = 11.6, zone = "1457" },
