      { only = "Tauren Druid",
        { "text", text = "Dreadmist Peak" },
        { "text", text = "Head north from the Crossroads to Dreadmist Peak and fill the |cOXP_LOOT_Empty Dreadmist Peak Sampler|r at the |cOXP_PICK_Dreadmist Peak Pool|r, then back to |cOXP_FRIENDLY_Tonga Runetotem|r in the Crossroads. No Herbalism? |cOXP_FRIENDLY_Hula'mahi|r beside him sells |cOXP_LOOT_Earthroot|r, three at a time until he restocks." },
        { "goto", only = "Tauren", x = 48.4, y = 18.9, zone = "1413" },
        { "complete", obj = 1, only = "Tauren", quest = 6127, text = "Filled Dreadmist Peak Sampler: 1" },
        { "goto", only = "Tauren", x = 52.26, y = 31.93, zone = "1413" },
        { "turnin", only = "Tauren", quest = 6127, text = "Turn in The Principal Source" },
