        { "goto", x = 51.39, y = 30.2, zone = "1413" },
        { "item", item = 2449, text = "Buy 5 Earthroot from |cOXP_FRIENDLY_Hula'mahi|r (|cOXP_LOOT_Earthroot|r from |cOXP_FRIENDLY_Hula'mahi|r; herbalists pick it on the plains)" },
        { "target", name = "Hula'mahi" },
      },
      { only = "Tauren Druid",
        { "text", text = "Kolkar camp" },
        { "text", text = "Lost Barrens Kodos roam the plains around the Kolkar camp north-west of |cOXP_FRIENDLY_Regthar Deathgate|r; herbalists pick |cOXP_LOOT_Earthroot|r there too." },
        { "goto", x = 54.82, y = 40.13, zone = "1413" },
